// Detection uses a server quote so the shown source is the one reserved.
export function detectionPriceReady(cap){return typeof cap.pointsCharged==='boolean'&&(!cap.pointsCharged||Number.isSafeInteger(cap.creditCost)&&cap.creditCost>0&&cap.creditCost<=100000&&Number.isSafeInteger(cap.pricingVersion));}
export function detectionPriceText(cap){return cap.pointsCharged?`${Number(cap.creditCost).toLocaleString('zh-CN')} 科研积分 / 次，适用权益优先`:'本次免费，无需消耗积分或套餐次数';}
export function detectionPriceSnapshot(cap){return Number.isSafeInteger(cap.pricingVersion)?{pricingVersion:cap.pricingVersion,expectedCreditCost:cap.pointsCharged?cap.creditCost:0}:{};}
export function detectionQuoteText(quote){switch(quote?.source){case 'free':return '本次免费，无需消耗积分或套餐次数';case 'membership':return `本次使用会员权益 ${quote.entitlementUnits||1} 次`;case 'bundle':return `本次使用专项套餐 ${quote.entitlementUnits||1} 次`;case 'credits':return `本次消耗 ${Number(quote.creditCost).toLocaleString('zh-CN')} 积分`;default:throw Error('费用信息暂不可用');}}
export function createDetectionQuote({request,checkOwner,current,element,onChange,serviceKey}){
 let quote=null,sequence=0,insufficient=false;const node=()=>element();
 async function refresh(){const n=++sequence;quote=null;insufficient=false;if(node())node().textContent='正在确认本次费用…';onChange();try{const next=await request('/billing/quote',{type:'agent',serviceKey});await checkOwner();if(n!==sequence||!current())return;const expiry=Date.parse(next?.expiresAt);if(!next?.token||!Number.isFinite(expiry)||expiry<=Date.now()||!['free','membership','bundle','credits'].includes(next.source)||next.source==='credits'&&(!Number.isSafeInteger(next.creditCost)||next.creditCost<1)||next.source!=='credits'&&next.creditCost!==0||next.entitlementUnits!==undefined&&(!Number.isSafeInteger(next.entitlementUnits)||next.entitlementUnits<1))throw Error('本次费用暂无法确认');quote=next;if(node())node().textContent=detectionQuoteText(next);}catch(error){if(n!==sequence||!current())return;insufficient=error.status===402;if(node())node().textContent=error.status===402?'可用积分或对应权益不足；相同内容的已有报告可直接查看。':'本次费用暂时无法确认，请重新获取。';}finally{if(n===sequence&&current())onChange();}}
 return {refresh,get ready(){return !!quote;},get insufficient(){return insufficient;},async token(){if(!quote||Date.parse(quote.expiresAt)<=Date.now()){await refresh();throw Object.assign(Error('费用已更新，请查看后再次点击开始检测。'),{publicMessage:'费用已更新，请查看后再次点击开始检测。'});}return quote.token;},invalidate(){quote=null;onChange();}};
}
